testo:
{
 "genere": "prevedi",
 "titolo": "Scegliere come tenere i dati",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted

func run():
	var items: Array[String] = ["pozione", "chiave", "spada"]
	return items[1]
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "Gli Array partono da indice 0. L'indice 0 è "pozione", mentre l'indice 1 è "chiave"."
  },
  {
   "codice": "extends RefCounted

func run():
	var inventory: Dictionary = {"gold": 50, "gems": 2}
	return inventory.get("silver", 0)
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "Il Dictionary non contiene la chiave "silver". Il metodo `get("silver", 0)` cerca la chiave e, se non la trova, restituisce il valore predefinito specificato come secondo argomento, cioè 0."
  },
  {
   "codice": "class ItemData extends RefCounted:
	var name: String = ""
	var count: int = 0
	func _init(p_name: String, p_count: int):
		name = p_name
		count = p_count

extends RefCounted

func run():
	var potion = ItemData.new("Pozione", 5)
	potion.count -= 2
	return potion.count
",
   "domanda": "Quanto vale `potion.count` alla fine?",
   "spiegazione": "La classe `ItemData` (derivata da RefCounted) viene creata con count pari a 5. Eseguendo `potion.count -= 2`, il valore finale all'interno dell'oggetto diventa 3."
  },
  {
   "codice": "extends RefCounted

func run():
	var stats: Dictionary = {"hp": 100, "mana": 50}
	var has_stamina: bool = stats.has("stamina")
	return has_stamina
",
   "domanda": "Il valore restituito è vero o falso?",
   "spiegazione": "Il metodo `has("stamina")` verifica se la chiave "stamina" esiste nel Dictionary `stats`. Poiché non è presente, restituisce `false`."
  }
 ]
